mapper.sql:
Timestamp BETWEEN fromUnixTimestamp64Milli(#{from}) AND fromUnixTimestamp64Milli(#{to})

    AND ServiceName = #{service}


    AND TraceId = #{traceId}


    AND SpanId = #{spanId}


    AND ResourceAttributes['deployment.environment.name'] = #{environment}


    AND (
        ResourceAttributes['service.namespace'] = #{namespace}
        OR if(indexOf(mapKeys(ResourceAttributes), 'k8s.namespace.name') = 0, '',
            arrayElement(mapValues(ResourceAttributes), indexOf(mapKeys(ResourceAttributes), 'k8s.namespace.name'))) = #{namespace}
    )


    AND if(indexOf(mapKeys(ResourceAttributes), 'k8s.namespace.name') = 0, '',
        arrayElement(mapValues(ResourceAttributes), indexOf(mapKeys(ResourceAttributes), 'k8s.namespace.name'))) = #{k8sNamespace}


    AND if(indexOf(mapKeys(ResourceAttributes), 'k8s.pod.name') = 0, '',
        arrayElement(mapValues(ResourceAttributes), indexOf(mapKeys(ResourceAttributes), 'k8s.pod.name'))) = #{k8sPodName}


    AND if(indexOf(mapKeys(ResourceAttributes), 'k8s.node.name') = 0, '',
        arrayElement(mapValues(ResourceAttributes), indexOf(mapKeys(ResourceAttributes), 'k8s.node.name'))) = #{k8sNodeName}


    AND if(indexOf(mapKeys(ResourceAttributes), 'service.instance.id') = 0, '',
        arrayElement(mapValues(ResourceAttributes), indexOf(mapKeys(ResourceAttributes), 'service.instance.id'))) = #{serviceInstanceId}


    AND SeverityText IN
    #{sev}


    AND (positionCaseInsensitive(Body, #{q}) > 0 OR position(TraceId, #{q}) > 0)

mapper.select:
SELECT toUnixTimestamp64Milli(Timestamp) AS timestamp, TraceId AS traceId, SpanId AS spanId, SeverityText AS severity, ServiceName AS service, Body AS body, ResourceAttributes AS resourceAttributes FROM quasar_tracing.logs
ORDER BY Timestamp DESC
LIMIT ${limit} OFFSET ${offset}

SELECT toUnixTimestamp64Milli(Timestamp) AS timestamp, TraceId AS traceId, SpanId AS spanId, SeverityText AS severity, ServiceName AS service, Body AS body, ResourceAttributes AS resourceAttributes FROM quasar_tracing.logs
AND toUnixTimestamp64Milli(Timestamp) > #{cursor}
ORDER BY Timestamp ASC, ServiceName, TraceId, SpanId
LIMIT ${limit}
